import type {
    SitePackageRevisionState,
    SitePackageRuntimeMode
} from '@/ports/repositories';

export interface SitePackageRevisionResponse {
    id: string;
    packageId: string;
    revisionNumber: number;
    entryPath: string;
    runtimeMode: SitePackageRuntimeMode;
    state: SitePackageRevisionState;
    fileCount: number;
    totalBytes: number;
    sourceSha256: string;
    createdBy: number;
    createdAt: number;
    publishedAt: number | null;
}

export interface SitePackageResponse {
    id: string;
    slug: string;
    title: string;
    description: string;
    publishedRevisionId: string | null;
    createdBy: number;
    updatedBy: number;
    createdAt: number;
    updatedAt: number;
    contentOrigin: string;
    revisions: SitePackageRevisionResponse[];
}

export interface ListSitePackagesResponse {
    packages: SitePackageResponse[];
}

export interface CreateSitePackageResponse {
    success: true;
    packageId: string;
    revisionId: string;
    previewUrl: string;
    previewToken: string;
    warnings: readonly string[];
    hasScripts: boolean;
}

export interface CreateSitePackageRevisionResponse {
    success: true;
    revision: SitePackageRevisionResponse;
    previewUrl: string;
    previewToken: string;
    warnings: readonly string[];
    hasScripts: boolean;
}

export interface PublishSitePackageRevisionResponse {
    success: true;
    packageId: string;
    revisionId: string;
    publishedAt: number | null;
    operation: 'publish' | 'rollback' | 'noop';
}

export interface RotateSitePackagePreviewTokenResponse {
    success: true;
    packageId: string;
    revisionId: string;
    previewToken: string;
    previewUrl: string;
}

export interface PublicSitePackageResponse {
    slug: string;
    title: string;
    description: string;
    revisionId: string;
    revisionNumber: number;
    runtimeMode: SitePackageRuntimeMode;
    publishedAt: number;
    siteUrl: string;
    contentUrl: string;
}

export interface SitePackageErrorResponse {
    error: string;
}

export interface SitePackageNotFoundResponseBoundary {
    readonly body: ReadableStream<Uint8Array> | null;
    readonly headers: Headers;
    readonly status: number;
}

export type SitePackageShellResponseBoundary = SitePackageNotFoundResponseBoundary;

export type PublishedSitePackageContentResponseBoundary = SitePackageNotFoundResponseBoundary;

export type PreviewSitePackageContentResponseBoundary = SitePackageNotFoundResponseBoundary;
